import requests

MAX_NOTES_CHARS = 2500


def _build_payload(repo_name, tag, release_notes, mention_group):
    notes = release_notes.strip()
    if len(notes) > MAX_NOTES_CHARS:
        notes = notes[:MAX_NOTES_CHARS].rstrip() + "\n... (truncated)"
    header = f"*{repo_name}* released `{tag}`"
    if mention_group:
        header = f"<!subteam^{mention_group}> {header}"
    release_url = f"https://github.com/{repo_name}/releases/tag/{tag}"
    return {
        "text": header,
        "blocks": [
            {"type": "section", "text": {"type": "mrkdwn", "text": header}},
            {"type": "section", "text": {"type": "mrkdwn", "text": notes}},
            {
                "type": "context",
                "elements": [{"type": "mrkdwn", "text": f"<{release_url}|View release>"}],
            },
        ],
    }


def post_release_announcement(webhook_url: str, repo_name: str, tag: str, release_notes: str, mention_group: str = None) -> dict:
    if not webhook_url.startswith("https://"):
        return {"ok": False, "error": "webhook_url must use https"}
    if "/" not in repo_name:
        return {"ok": False, "error": "repo_name must look like owner/name"}
    if not tag.strip():
        return {"ok": False, "error": "tag is required"}
    payload = _build_payload(repo_name, tag.strip(), release_notes, mention_group)
    try:
        response = requests.post(webhook_url, json=payload, timeout=15)
        response.raise_for_status()
    except requests.RequestException as exc:
        return {"ok": False, "error": str(exc)}
    return {"ok": True, "status_code": response.status_code, "tag": tag, "repo": repo_name}

import os

from github import Github

_client = Github(os.environ["GITHUB_TOKEN"])


def _get_repo(repo_name):
    return _client.get_repo(repo_name)


def grant_repo_collaborator_access(repo_name: str, username: str, permission: str = "push") -> dict:
    if permission not in ("pull", "triage", "push", "maintain", "admin"):
        return {"ok": False, "error": f"invalid permission: {permission}"}
    repo = _get_repo(repo_name)
    invitation = repo.add_to_collaborators(username, permission=permission)
    return {"ok": True, "repo": repo_name, "user": username, "permission": permission, "invitation_id": getattr(invitation, "id", None)}

import re
import subprocess
import sys
from pathlib import Path

from agents import function_tool

_SUMMARY_RE = re.compile(r"=+ (.*?) in ([\d.]+)s.*=+\s*$")
_FAILED_RE = re.compile(r"^FAILED (\S+)", re.MULTILINE)


def _summarize(output, max_failures):
    failed = _FAILED_RE.findall(output)[:max_failures]
    summary = None
    for line in reversed(output.strip().splitlines()):
        match = _SUMMARY_RE.search(line)
        if match:
            summary = match.group(1)
            break
    return summary, failed


@function_tool
def run_repo_tests(repo_path: str, test_path: str = "tests", timeout_seconds: int = 300, max_failures: int = 10) -> dict:
    root = Path(repo_path).expanduser().resolve()
    if not root.is_dir():
        return {"error": f"not a directory: {root}"}
    target = root / test_path
    if not target.exists():
        return {"error": f"test path not found: {test_path}"}
    cmd = [sys.executable, "-m", "pytest", str(target), "-q", "-rf", "--maxfail=50", "-p", "no:cacheprovider"]
    timed_out = False
    with subprocess.Popen(cmd, cwd=root, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True) as proc:
        try:
            output, _ = proc.communicate(timeout=timeout_seconds)
        except subprocess.TimeoutExpired:
            proc.kill()
            output, _ = proc.communicate()
            timed_out = True
    summary, failed = _summarize(output or "", max_failures)
    return {
        "exit_code": proc.returncode,
        "timed_out": timed_out,
        "summary": summary,
        "failed_tests": failed,
        "output_tail": (output or "")[-1500:],
    }

import stripe
from agents import function_tool

from ci_billing import billing_client

PRICE_CENTS_PER_MINUTE = 1


@function_tool
def buy_ci_minutes_for_repo(repo_name: str, minutes: int, customer_id: str) -> dict:
    if "/" not in repo_name:
        return {"ok": False, "error": "repo_name must look like owner/name"}
    if minutes <= 0 or minutes % 500 != 0:
        return {"ok": False, "error": "minutes must be a positive multiple of 500"}
    remaining = billing_client.get_remaining_minutes(repo_name)
    intent = stripe.PaymentIntent.create(amount=minutes * PRICE_CENTS_PER_MINUTE, currency="usd", customer=customer_id, confirm=True, off_session=True, metadata={"repo": repo_name, "minutes": minutes})
    return {"ok": intent.status == "succeeded", "previous_minutes": remaining, "charged_cents": intent.amount, "payment_id": intent.id}
